/* ===== Round 2: vendor/provider dashboards ===== */
const mediaConsent=(on,act)=>`<div class="card pad stack" style="border-color:var(--secondary)"><label class="row between" style="gap:12px;align-items:flex-start"><span><b>${t('Also show this in my business Gallery / Videos & Reels')}</b><span class="small t2" style="display:block">${t('If on, photos and videos you add here also appear in your public Gallery and Reels. If off, they show only on this page.')} ${t('Default comes from your Gallery settings.')}</span></span><span class="toggle"><input type="checkbox" ${on?'checked':''} data-chg="${act}" data-k="inGallery" aria-label="${t('Show in Gallery')}"><span></span></span></label><input type="hidden" name="inGallery" id="h_inGallery" value="${on?1:0}"></div>`;
/* ---- Services manager ---- */
V.vservices=()=>{if(!canAct(MYROLE()))return lockedMsg(MYROLE());const x=vb(),l=x.services||[];
 return `<div class="stack"><div class="row between wrap-r"><h1>${t('Services')}</h1><button class="btn p sm" data-act="svEdit" data-id="">${ic('plus',16)} ${t('Add service')}</button></div>${alertBox('info',t('Each service gets its own page with a Send enquiry form. Pick one subcategory per service. These power the Explore and Search filters.'))}${l.length?`<div class="stack">${l.map(s=>`<div class="card pad stack ${s.active===false?'':''}" style="${s.active===false?'opacity:.75':''}"><div class="row between wrap-r" style="align-items:flex-start"><div class="grow"><b>${esc(s.n)}</b> ${s.active===false?`<span class="badge neu">${t('Paused')}</span>`:`<span class="badge ok">● ${t('Active')}</span>`}<div class="small t2">${esc(catName(s.cat))} › ${esc(subLabel(s.sub))} · ${svPrice(s)}</div></div><span class="toggle"><input type="checkbox" ${s.active!==false?'checked':''} data-chg="svAct" data-id="${s.id}" aria-label="${t('Active')}: ${esc(s.n)}"><span></span></span></div><div class="row wrap-r"><button class="btn g sm" data-act="svEdit" data-id="${s.id}">${ic('edit',14)} ${t('Edit')}</button><a class="btn g sm" href="#service-${s.id}">${ic('eye',14)} ${t('View page')}</a><button class="btn g sm" data-act="copy" data-v="${esc(shareUrl('service-'+s.id))}">${ic('copy',14)} ${t('Copy link')}</button><button class="btn t sm" data-act="svDel" data-id="${s.id}" aria-label="${t('Delete')} ${esc(s.n)}">${ic('trash',16)}</button></div></div>`).join('')}</div>`:empty('🔧','No services yet','Add the services you offer. Each gets its own page.','<button class="btn p" data-act="svEdit" data-id="">'+t('Add your first service')+'</button>')}</div>`};
CH.svAct=el=>{const x=vb(),s=x.services.find(a=>a.id===el.dataset.id);s.active=el.checked;save();render(true);toast(el.checked?t('Service is active'):t('Service paused'))};
const PTYPES=[['from','Starting price (from)'],['fixed','Fixed price'],['range','Price range'],['enquiry','Price on enquiry']],UNITS=[['','—'],['/ hour','per hour'],['/ day','per day'],['/ event','per event'],['/ sq ft','per sq ft'],['/ unit','per unit'],['/ visit','per visit'],['/ plate','per plate']];
function svSubOpts(cat,cur){return svcSubs(cat).map(x=>`<option value="${x.slug}" ${x.slug===cur?'selected':''}>${esc(S.lang==='hi'&&x.hi?x.hi:x.en)}</option>`).join('')}
A.svEdit=el=>{const x=vb(),s=(x.services||[]).find(a=>a.id===el.dataset.id)||{id:'',n:'',cat:(SCATS.some(c=>c.id===x.cat)?x.cat:'wedding'),sub:'',ptype:'from',from:'',to:'',unit:'',desc:'',incl:[],excl:[],area:x.serviceArea||'Padrauna',imgs:[{t:'img',e:x.emoji,h:x.hue}],inGallery:x.mediaDefault!==false,active:true};UI.svImgs=JSON.parse(JSON.stringify(s.imgs||[]));
 sheet(`<div class="row between"><h3>${s.id?t('Edit service'):t('Add service')}</h3><button class="iconbtn" data-act="closeSheet" aria-label="${t('Close')}">${ic('x')}</button></div><form data-form="svc" class="stack" style="margin-top:10px"><input type="hidden" name="id" value="${s.id}">${field('Service title','n',s.n,{req:1})}<div class="grid g2">${field('Category','cat',s.cat,{type:'select',opts:SCATS.map(c=>[c.id,c.en])})}<div class="field"><label for="f_sub">${t('Subcategory')} *</label><select class="input" id="f_sub" name="sub" required>${svSubOpts(s.cat,s.sub)}</select><span class="hint">${t('One subcategory per service.')}</span></div></div>${field('Description','desc',s.desc,{type:'textarea'})}<div class="grid g2">${field('Price type','ptype',s.ptype||'from',{type:'select',opts:PTYPES})}${field('Unit','unit',s.unit||'',{type:'select',opts:UNITS})}${field('Amount (₹)','from',s.from===0?'':s.from,{type:'number',min:0})}${field('Up to (₹, for range)','to',s.to||'',{type:'number',min:0})}</div>${field('What is included (one per line)','incl',(s.incl||[]).join('\n'),{type:'textarea'})}${field('Not included (one per line)','excl',(s.excl||[]).join('\n'),{type:'textarea'})}${field('Service area','area',s.area)}
 <div class="card pad stack"><b class="small">${t('Photos')}</b><div class="row wrap-r" id="svimgs">${(UI.svImgs).map((m,i)=>`<span class="card" style="width:56px">${art(x.emoji,m.h,'')}</span>`).join('')}<button type="button" class="btn g sm" data-act="svImg">${ic('camera',14)} ${t('Add photo')}</button></div><div class="field"><label for="f_vl">${t('Video link (YouTube or Instagram, optional)')}</label><input class="input" id="f_vl" name="vlink" data-in="pmurlsv" placeholder="https://youtu.be/…"><div id="svv" class="small"></div></div></div>
 ${mediaConsent(s.inGallery!==false,'tgform')}<div class="card pad">${toggle('active',s.active!==false,'Service is active (visible to customers)','tgform')}<input type="hidden" name="active" id="h_active" value="${s.active!==false?1:0}"></div>${s.id?`<div class="field"><label>${t('Shareable link')}</label><div class="row"><input class="input" readonly value="${esc(shareUrl('service-'+s.id))}"><button type="button" class="btn g" data-act="copy" data-v="${esc(shareUrl('service-'+s.id))}">${ic('copy',16)}</button></div></div>`:''}<button class="btn p block">${t('Save service')}</button></form>`,{wide:true,label:'Service'})};
document.addEventListener('change',e=>{if(e.target.name==='cat'&&e.target.closest('form[data-form=svc]')){const f=e.target.form;f.elements.sub.innerHTML=svSubOpts(e.target.value,'')}});
INP.pmurlsv=v=>{$('#svv').innerHTML=embedPrev(v)};A.svImg=()=>{UI.svImgs.push({t:'img',e:'',h:(UI.svImgs.length*37+20)%360});const x=vb();$('#svimgs').insertAdjacentHTML('afterbegin',`<span class="card" style="width:56px">${art(x.emoji,UI.svImgs.at(-1).h,'')}</span>`)};
F.svc=d=>{const x=vb();x.services=x.services||[];const lines=s=>(s||'').split('\n').map(a=>a.trim()).filter(Boolean);let s=x.services.find(a=>a.id===d.id);const base={n:d.n,cat:d.cat,sub:d.sub,desc:d.desc,ptype:d.ptype,unit:d.unit,from:d.ptype==='enquiry'?0:(+d.from||0),to:+d.to||0,incl:lines(d.incl),excl:lines(d.excl),area:d.area,imgs:UI.svImgs.length?UI.svImgs:[{t:'img',e:'',h:30}],inGallery:d.inGallery==='1',active:d.active==='1'};base.p=base.ptype==='enquiry'?'on enquiry':(base.ptype==='from'?'from ':'')+inr(base.from)+(base.unit?' '+base.unit:'');
 if(s)Object.assign(s,base);else{s={id:x.id+'-sv'+Date.now().toString(36),exp:3,faq:[['How soon can you visit?','Usually the same or next day.']],...base};x.services.push(s)}
 const r=parseEmbed(d.vlink);if(d.vlink&&r.ok){x.media=x.media||[];x.media.push({id:rid('m'),t:r.t,vid:r.vid,url:r.url,reel:r.reel,title:s.n+' video',cap:s.n,hashtags:[],tags:[s.id],status:'pending',views:0,likes:0,shares:0,gained:0,taps:0,thumb:r.t==='yt'?'▶️':'📷',dur:20,ts:Date.now(),reels:s.inGallery,gal:s.inGallery,comments:[]});notify('admin','Video awaiting approval',nm(x.name)+': '+s.n,'avideos','review')}
 save();closeSheet();render(true);toast(t('Service saved'),'check')};
/* ---- Videos & reels manager + gallery manager ---- */
const stChip=s=>`<span class="badge ${s==='approved'?'ok':s==='pending'?'warn':s==='rejected'?'bad':'neu'}">${s==='approved'?'✓':s==='pending'?'⏳':s==='rejected'?'✕':'⊘'} ${t(({approved:'Approved',pending:'Pending approval',rejected:'Rejected',removed:'Removed'})[s]||s)}</span>`;
UI.vmTab='videos';
V.vmedia=()=>{if(!canAct(MYROLE()))return lockedMsg(MYROLE());const b=vb(),med=b.media||[];const tab=UI.vmTab;
 return `<div class="stack-lg"><h1>${t('Gallery & media')}</h1><div class="tabs">${[['videos','Videos & Reels'],['gallery','Gallery']].map(([k,l])=>`<button class="${tab===k?'on':''}" data-act="vmTab" data-v="${k}">${t(l)}</button>`).join('')}</div>
 ${tab==='gallery'?`<div class="card pad stack"><h3>${t('Gallery settings')}</h3><label class="row between" style="gap:12px;align-items:flex-start"><span><b>${t('Default for new product and service media')}</b><span class="small t2" style="display:block">${t('When on, photos and videos you add to a product or service also appear in your public Gallery. You can change it for each item.')}</span></span><span class="toggle"><input type="checkbox" ${b.mediaDefault!==false?'checked':''} data-chg="mdDef" aria-label="${t('Default')}"><span></span></span></label></div>
 <div class="card pad stack"><h3>${t('Gallery-only photos')}</h3><p class="small t2">${t('These are not linked to any product or service.')}</p>${uploader('Add photos (4:3)')}<div class="grid g3">${b.gallery.map((g,i)=>`<div class="stack" style="gap:4px">${art(g,b.hue+i*20,'f')}<div class="row"><button class="iconbtn" style="width:36px;height:36px" data-act="gmove" data-i="${i}" data-d="-1" aria-label="${t('Move left')}" ${i?'':'disabled'}>${ic('cl',16)}</button><button class="iconbtn" style="width:36px;height:36px" data-act="gmove" data-i="${i}" data-d="1" aria-label="${t('Move right')}" ${i<b.gallery.length-1?'':'disabled'}>${ic('cr',16)}</button><button class="iconbtn" style="width:36px;height:36px" data-act="gdel" data-i="${i}" aria-label="${t('Delete')}">${ic('trash',16)}</button></div></div>`).join('')}</div></div><div class="card pad stack"><h3>${t('Shown from products and services')}</h3>${galItems(b).filter(i=>i.link).map(i=>`<div class="row between small"><span>${i.link.t==='p'?'🛍':'🔧'} ${esc(i.link.n)}</span><span class="badge ok">${t('In Gallery')}</span></div>`).join('')||`<span class="muted small">${t('Nothing yet.')}</span>`}</div>`
 :`<div class="card pad stack"><h3>${t('Add a video or reel')}</h3><p class="small t2">${t('Paste a YouTube video, YouTube Shorts or Instagram reel link, or upload a video. New videos are reviewed by an admin before they appear.')}</p><form data-form="mediaAdd2" class="stack"><div class="field"><label for="mu">${t('Link')}</label><input class="input" id="mu" name="url" data-in="mediaUrl" placeholder="https://www.youtube.com/watch?v=…" autocomplete="off"><div id="mprev"></div></div><button type="button" class="btn g sm" data-act="fakeUpload" style="justify-self:start">${ic('upload',14)} ${t('Upload a video file')}</button>${field('Caption','cap','',{type:'textarea'})}${field('Hashtags (comma separated)','hashtags','',{ph:'#iPhone15, #Padrauna'})}<div><div class="lbl small">${t('Thumbnail')}</div><div class="chips">${['📱','🛍️','🎬','✨','🏠','🎉'].map((e,i)=>`<label class="chip"><input type="radio" name="thumb" value="${e}" ${i?'':'checked'} style="accent-color:var(--primary)"> ${e}</label>`).join('')}</div></div><label class="check"><input type="checkbox" name="gal" checked style="accent-color:var(--primary)">${t('Show in Gallery')}</label><label class="check"><input type="checkbox" name="reels" checked style="accent-color:var(--primary)">${t('Show in Reels feed')}</label><button class="btn p">${ic('plus',16)} ${t('Submit for approval')}</button></form></div>
 ${med.length?med.map((m,i)=>`<div class="card pad stack"><div class="row">${art(m.thumb,m.t==='yt'?0:330,'mini')}<div class="grow"><b>${esc(m.title)}</b><div class="small t2">${mLabel(m)} · ${mKind(m)==='reel'?t('Reel'):t('Video')} · ${stChip(m.status)}</div></div><button class="iconbtn" style="width:40px;height:40px" data-act="mvMove" data-i="${i}" data-d="-1" ${i?'':'disabled'} aria-label="${t('Move up')}">${ic('cu',16)}</button><button class="iconbtn" style="width:40px;height:40px" data-act="mvMove" data-i="${i}" data-d="1" ${i<med.length-1?'':'disabled'} aria-label="${t('Move down')}">${ic('cd',16)}</button></div>${m.reason?alertBox('bad',`<b>${t('Rejected')}:</b> ${esc(m.reason)}`):''}<div class="small t2">${esc(m.cap)} ${(m.hashtags||[]).map(esc).join(' ')}</div><div class="row wrap-r" style="gap:6px"><b class="small">${t('Linked')}:</b>${(m.tags||[]).map(tagItem).filter(Boolean).map(i=>`<span class="chip" style="min-height:32px">${esc(i.name)}</span>`).join('')||`<span class="muted small">${t('Nothing linked yet')}</span>`}</div><div class="grid g2"><label class="row between" style="gap:8px"><span class="small">${t('Show in Gallery')}</span><span class="toggle"><input type="checkbox" ${m.gal!==false?'checked':''} data-chg="mvVis" data-i="${i}" data-k="gal" aria-label="${t('Show in Gallery')}"><span></span></span></label><label class="row between" style="gap:8px"><span class="small">${t('Show in Reels feed')}</span><span class="toggle"><input type="checkbox" ${m.reels!==false?'checked':''} data-chg="mvVis" data-i="${i}" data-k="reels" aria-label="${t('Show in Reels feed')}"><span></span></span></label></div><div class="grid g3 center" style="grid-template-columns:repeat(5,1fr);gap:6px">${[['Views',m.views],['Likes',m.likes],['Shares',m.shares],['Followers gained',m.gained],['Taps on linked',m.taps]].map(([l,n])=>`<div class="card pad" style="padding:8px 4px"><b>${fmtN(n)}</b><div class="xs muted">${t(l)}</div></div>`).join('')}</div><div class="row wrap-r"><button class="btn o sm" data-act="tagPick" data-i="${i}">${ic('tag',14)} ${t('Link products or services')}</button><button class="btn g sm" data-act="playMedia" data-o="${b.id}" data-m="${m.id}">${ic('eye',14)} ${t('Preview')}</button><button class="btn t sm" data-act="mvDel" data-i="${i}" style="color:var(--error)">${ic('trash',14)} ${t('Remove')}</button></div></div>`).join(''):empty('🎬','No videos or reels yet','Paste a link above to add your first one.')}`}</div>`};
A.vmTab=el=>{UI.vmTab=el.dataset.v;render(true)};CH.mdDef=el=>{vb().mediaDefault=el.checked;save();toast(t('Saved'))};
CH.mvVis=el=>{vb().media[+el.dataset.i][el.dataset.k]=el.checked;save();toast(t('Updated'))};
F.mediaAdd2=d=>{const r=parseEmbed(d.url);if(!r.ok){$('#mprev').innerHTML=embedPrev(d.url||' ')||`<div class="errmsg" role="alert">${t('Paste a YouTube or Instagram link.')}</div>`;toast(t(r.err),'alert');return}const b=vb();b.media=b.media||[];b.media.push({id:rid('m'),t:r.t,vid:r.vid,url:r.url,reel:r.reel,title:(d.cap||'').slice(0,40)||mLabel(r)+(r.reel?' reel':' video'),cap:d.cap||'',hashtags:(d.hashtags||'').split(',').map(x=>x.trim()).filter(Boolean),tags:[],status:'pending',views:0,likes:0,shares:0,gained:0,taps:0,thumb:d.thumb,dur:20,ts:Date.now(),reels:!!d.reels,gal:!!d.gal,comments:[]});notify('admin','Video awaiting approval',nm(b.name)+': '+(d.cap||'new video').slice(0,40),'avideos','review');save();render(true);toast(t('Submitted. An admin will review it.'),'send')};
/* ---- followers ---- */
V.vfollow=()=>{if(!canAct(MYROLE()))return lockedMsg(MYROLE());const x=vb(),n=followers(x);const ser=series(x.id,8,Math.max(2,Math.round(n/12)),Math.max(3,Math.round(n/10)));let run=n-ser.reduce((a,b)=>a+b,0);run=Math.max(0,run);const cum=ser.map(v=>run+=v);
 return `<div class="stack-lg"><h1>${t('Followers')}</h1><div class="grid g3">${kpi('Followers',n,'6%')}${kpi('Gained this week',ser.slice(-7).reduce((a,b)=>a+b,0),'')}${kpi('Videos',(x.media||[]).filter(m=>m.status==='approved').length,'')}</div><div class="card pad stack"><h3>${t('Follower growth, last 8 weeks')}</h3>${barChart(cum,['W1','W2','W3','W4','W5','W6','W7','W8'])}</div><div class="card pad stack"><h3>${t('Announce to followers')}</h3><form data-form="announce" class="stack">${field('Message','msg','',{type:'textarea',req:1,ph:'New offer or video'})}<div class="chips"><label class="chip"><input type="radio" name="kind" value="offer" checked> ${t('New offer')}</label><label class="chip"><input type="radio" name="kind" value="video"> ${t('New video')}</label></div><button class="btn p">${ic('send',16)} ${t('Send to')} ${n} ${t('followers')}</button></form>${(D().notices||[]).filter(a=>a.o===x.id).slice(0,3).map(a=>`<div class="small t2">• ${fdt(a.ts)}: ${esc(a.msg)} (${a.n} ${t('followers')})</div>`).join('')}</div></div>`};
V.sfollow=V.vfollow;
F.announce=d=>{const x=vb(),n=followers(x);D().notices.unshift({id:rid('n'),o:x.id,msg:d.msg,kind:d.kind,n,ts:Date.now()});if(isFollow(x.id))notify('cust',nm(x.name)+': '+(d.kind==='video'?'new video':'new offer'),d.msg,d.kind==='video'?'videos':'offers','offer');save();render(true);toast(t('Sent to your followers'),'send')};
/* ---- product category pills manager ---- */
A.pillMgr=()=>{const x=vb(),subs=[...new Set(D().products.filter(p=>p.bid===x.id).map(p=>p.sub))],list=pillList({...x},subs).map(p=>p.k),all=[...list,...subs.filter(k=>!list.includes(k))];UI.pm2=all.map(k=>({k,hidden:x.pill.hidden.includes(k),label:x.pill.rename[k]||k}));pillSheet()};
function pillSheet(){sheet(`<div class="row between"><h3>${t('Manage category pills')}</h3><button class="iconbtn" data-act="closeSheet" aria-label="${t('Close')}">${ic('x')}</button></div><p class="small t2">${t('Reorder, rename or hide the pills customers see above your products.')}</p><form data-form="pills" class="stack" style="margin-top:10px">${UI.pm2.map((p,i)=>`<div class="card pad row" style="gap:6px"><button type="button" class="iconbtn" style="width:40px;height:40px" data-act="pillMove" data-i="${i}" data-d="-1" ${i?'':'disabled'} aria-label="${t('Move up')}">${ic('cu',16)}</button><button type="button" class="iconbtn" style="width:40px;height:40px" data-act="pillMove" data-i="${i}" data-d="1" ${i<UI.pm2.length-1?'':'disabled'} aria-label="${t('Move down')}">${ic('cd',16)}</button><input class="input grow" name="r_${i}" value="${esc(p.label)}" aria-label="${t('Rename')} ${esc(p.k)}"><label class="check" style="min-height:44px"><input type="checkbox" name="h_${i}" ${p.hidden?'checked':''} style="accent-color:var(--primary)">${t('Hide')}</label></div>`).join('')}<button class="btn p">${t('Save pills')}</button></form>`,{wide:true,label:'Pills'})}
A.pillMove=el=>{const l=UI.pm2,i=+el.dataset.i,j=i+ +el.dataset.d;const f=$('form[data-form=pills]');l.forEach((p,k)=>{p.label=f.elements['r_'+k].value;p.hidden=f.elements['h_'+k].checked});[l[i],l[j]]=[l[j],l[i]];pillSheet()};
F.pills=d=>{const x=vb();x.pill={order:UI.pm2.map(p=>p.k),hidden:UI.pm2.filter((p,i)=>d['h_'+i]).map(p=>p.k),rename:Object.fromEntries(UI.pm2.map((p,i)=>[p.k,d['r_'+i]]).filter(([k,v])=>v&&v!==k))};save();closeSheet();render(true);toast(t('Pills saved'),'check')};
V.sservices=V.vservices;V.smedia=V.vmedia;
